import { z } from 'zod';
import { POWER_CLASSES } from '../domain/hero.model';

/**
 * The hero edit form's schema. It is the single source of truth for the shape,
 * the rules, and the field labels. Validation runs through `validateStandardSchema`.
 */
export const heroSchema = z.object({
  name: z
    .string()
    .trim()
    .min(1, { error: 'Name is required' })
    .max(60, { error: 'Name must be 60 characters or fewer' })
    .meta({ label: 'Hero name', control: 'text', placeholder: 'e.g. Silverwing' }),
  alias: z
    .string()
    .trim()
    .min(1, { error: 'Alias is required' })
    .max(60, { error: 'Alias must be 60 characters or fewer' })
    .meta({ label: 'Alias', control: 'text' }),
  powerClass: z.enum(POWER_CLASSES).meta({
    label: 'Power class',
    control: 'select',
    options: POWER_CLASSES.map((value) => ({ value, label: value })),
  }),
  powerIndex: z
    .number({ error: 'Power index must be a number' })
    .int({ error: 'Power index must be a whole number' })
    .min(0, { error: 'Power index must be between 0 and 100' })
    .max(100, { error: 'Power index must be between 0 and 100' })
    .meta({ label: 'Power index', control: 'number' }),
});

export type HeroModel = z.infer<typeof heroSchema>;
==== src/app/ui/hero-card/hero-card.ts
import { Component, computed, input, output } from '@angular/core';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmCardImports } from '@spartan-ng/helm/card';
import type { Hero } from '../../domain/hero.model';
import { PowerMeter } from '../power-meter/power-meter';

/** One hero as a card. Presentational: the hero arrives as an input and the open action leaves as an output. */
@Component({
  selector: 'app-hero-card',
  imports: [HlmAvatarImports, HlmBadgeImports, HlmButtonImports, HlmCardImports, PowerMeter],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();
  readonly open = output<Hero>();

  /** Up to two initials from the hero's name, for the avatar fallback. */
  protected readonly initials = computed(() =>
    this.hero()
      .name.split(/\s+/)
      .filter(Boolean)
      .map((word) => word[0])
      .join('')
      .slice(0, 2)
      .toUpperCase(),
  );

  /** A missing hero is the one status the cards flag in the destructive colour. */
  protected readonly statusVariant = computed<'destructive' | 'secondary'>(() =>
    this.hero().status === 'MIA' ? 'destructive' : 'secondary',
  );
}
